-- Runs real database writes, role checks and storage-policy checks, then rolls back all fixtures.
begin;
do $$
declare a uuid; a_email text; f uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); buyer uuid:=gen_random_uuid(); oid uuid:=gen_random_uuid();
 req jsonb:='[{"id":"sample","stage":"sample","label":"Approved sample","criteria":"Matches tech pack"},{"id":"chest","stage":"final","label":"Chest","criteria":"56 cm +/- 1 cm","target":56,"tolerance":1,"unit":"cm"}]';
 payload jsonb; sample_id uuid; final_id uuid; fail_id uuid; defect_id uuid; release_id uuid; path text; passed boolean;
begin
 select u.id,u.email into a,a_email from auth.users u join public.superadmin_emails s on lower(s.email)=lower(u.email) limit 1;
 if a is null then raise exception 'An existing allowlisted admin is required for live QC verification';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email',a_email,'role','authenticated')::text,true);
 insert into auth.users(id,email,raw_user_meta_data) values(f,'qc-factory-'||f||'@example.invalid','{}'),(outsider,'qc-other-'||outsider||'@example.invalid','{}'),(buyer,'qc-buyer-'||buyer||'@example.invalid','{}');
 insert into public.manufacturer_profiles(user_id,factory_name,onboarding_complete,status)values(f,'QC rollback verification factory',true,'active');
 insert into public.orders(id,user_id,kind,product_name,garment_type,status,status_label)values(oid,buyer,'production','QC rollback verification','Hoodies','submitted','Submitted');
 perform set_config('app.routing_write',oid::text,true);
 perform set_config('app.workflow_write',oid::text,true);
 update public.orders set assigned_manufacturer_id=f,production_released_at=now(),status='processing',selected_price_option_id='bulk',price_options='[{"id":"bulk","totalUnits":10}]' where id=oid;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email',a_email,'role','authenticated')::text,true);
 perform public.qc_action(oid,'requirements',jsonb_build_object('checks',req));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',f,'email','qc-factory@example.invalid','role','authenticated')::text,true);
 payload:=jsonb_build_object('stage','sample','batch','S1','produced',1,'inspected',1,'accepted',1,'rejected',0,'held',0,'checks','[{"id":"sample","result":"pass","note":"Matches"}]'::jsonb);
 sample_id:=public.qc_action(oid,'submit_inspection',payload);
 passed:=false;begin perform public.qc_action(oid,'review_inspection',jsonb_build_object('id',sample_id,'note','Bypass'));exception when others then passed:=true;end;
 if not passed then raise exception 'Manufacturer bypassed Ceriga approval';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email',a_email,'role','authenticated')::text,true);
 perform public.qc_action(oid,'review_inspection',jsonb_build_object('id',sample_id,'note','Rollback test sample approved'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',f,'email','qc-factory@example.invalid','role','authenticated')::text,true);
 payload:=jsonb_build_object('stage','final','batch','B1','produced',10,'inspected',10,'accepted',9,'rejected',0,'held',1,'checks','[{"id":"chest","actual":57.5,"result":"pass","note":"Too wide","severity":"major","affected_units":1}]'::jsonb);
 fail_id:=public.qc_action(oid,'submit_inspection',payload);
 if (select result from public.qc_inspections where id=fail_id)<>'failed' then raise exception 'Measurement failure was not detected';end if;
 select id into defect_id from public.qc_defects where inspection_id=fail_id;
 perform public.qc_action(oid,'defect',jsonb_build_object('id',defect_id,'status','rework','resolution','Correct chest width'));
 path:=oid||'/'||f||'/verification.png';
 insert into storage.objects(bucket_id,name)values('qc-evidence',path);
 perform public.qc_action(oid,'evidence',jsonb_build_object('defect_id',defect_id,'path',path,'file_name','verification.png'));
 perform public.qc_action(oid,'defect',jsonb_build_object('id',defect_id,'status','awaiting_reinspection','resolution','Rework completed with evidence'));
 perform public.qc_action(oid,'submit_inspection',jsonb_build_object('stage','reinspection','parent_defect_id',defect_id,'batch','B1 rework','produced',1,'inspected',1,'accepted',1,'rejected',0,'held',0,'checks','[{"id":"chest","actual":56,"result":"pass","note":"Corrected"}]'::jsonb));
 if (select status from public.qc_defects where id=defect_id)<>'closed' then raise exception 'Reinspection did not close defect';end if;
 payload:=jsonb_set(jsonb_set(payload,'{accepted}','10'),'{held}','0');payload:=jsonb_set(payload,'{checks}','[{"id":"chest","actual":56,"result":"pass","note":"Final batch passed"}]');
 final_id:=public.qc_action(oid,'submit_inspection',payload);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'email',a_email,'role','authenticated')::text,true);
 release_id:=public.qc_action(oid,'release',jsonb_build_object('inspection_id',final_id,'quantity',10,'reason','Rollback verification release'));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',f,'email','qc-factory@example.invalid','role','authenticated')::text,true);
 perform public.qc_action(oid,'dispatch',jsonb_build_object('id',release_id,'tracking','QC-ROLLBACK-ONLY'));
 if (select status from public.orders where id=oid)<>'shipping' then raise exception 'Dispatch did not persist';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'email','outsider@example.invalid','role','authenticated')::text,true);
 if public.qc_can_access(oid) then raise exception 'Unassigned user has QC access';end if;
 passed:=false;begin perform public.qc_action(oid,'save_inspection',payload);exception when others then passed:=true;end;
 if not passed then raise exception 'Unassigned user wrote QC data';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',buyer,'email','buyer@example.invalid','role','authenticated')::text,true);
 if public.qc_can_access(oid) then raise exception 'Buyer can read internal QC';end if;
 -- Exercise actual table RLS and storage SELECT as an ordinary authenticated user.
 execute 'set local role authenticated';
 if exists(select 1 from public.qc_inspections where order_id=oid) or exists(select 1 from storage.objects where bucket_id='qc-evidence' and name=path) then raise exception 'RLS exposed internal QC';end if;
 execute 'reset role';
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname like 'qc_%' and c.relkind='r' and not c.relrowsecurity) then raise exception 'QC table missing RLS';end if;
 if has_function_privilege('anon','public.qc_action(uuid,text,jsonb)','execute') or has_function_privilege('authenticated','public.apply_superadmin_access()','execute') then raise exception 'Incorrect workflow grants';end if;
end $$;
rollback;
select 'PASS: live sample approval, measurement failure, defects, private evidence, reinspection, release, dispatch and account isolation; all fixtures rolled back' as qc_verification;
